#!/usr/bin/env node
// Generates the committed Nucleo subset (ADR 009) from a licensed install.
//
// Usage: node scripts/generate-icons.mjs <path/to/licensed/node_modules>
//
// The node_modules directory lives outside the repository and must contain
// nucleo-ui-fill-18 and nucleo-micro-bold (with their react peer). Only the
// SVG paths are copied; generated files have no runtime dependency on Nucleo.

import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const packageDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const repoDir = path.resolve(packageDir, "../..");
const iconDir = path.join(packageDir, "src/icon");
const outDir = path.join(iconDir, "nucleo");
const MAX_GLYPHS = 100;

const SETS = {
  "ui-fill-18": { pkg: "nucleo-ui-fill-18", version: "1.5.1", stroke: false },
  "micro-bold": { pkg: "nucleo-micro-bold", version: "1.2.1", stroke: true },
};

function fail(message) {
  console.error(`generate-icons: ${message}`);
  process.exit(1);
}

function formatNotice(text) {
  const lines = text.trimEnd().split("\n");
  return `/*\n${lines.map((line) => (line ? ` * ${line}` : " *")).join("\n")}\n */\n`;
}

function componentName(name) {
  return `${name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")}Icon`;
}

function isElement(node) {
  return typeof node === "object" && node !== null && "type" in node && "props" in node;
}

function flatten(children) {
  if (Array.isArray(children)) return children.flatMap(flatten);
  return isElement(children) ? [children] : [];
}

function renderAttribute(key, value, stroke) {
  if (stroke && key === "strokeWidth") return "strokeWidth={strokeWidth}";
  if (typeof value !== "string" && typeof value !== "number") {
    fail(`unsupported attribute ${key}=${String(value)}`);
  }
  const text = String(value);
  if (text.includes('"')) fail(`attribute ${key} contains a double quote`);
  return `${key}="${text}"`;
}

function renderNode(node, stroke, depth) {
  if (typeof node.type !== "string") fail("nested component inside a glyph");
  const indent = "  ".repeat(depth);
  const { children, ...attributes } = node.props;
  if ("id" in attributes) fail(`glyph uses an id (${attributes.id}); ids collide across icons`);
  const attrs = Object.entries(attributes)
    .map(([key, value]) => renderAttribute(key, value, stroke))
    .join(" ");
  const kids = flatten(children);
  if (kids.length === 0) return `${indent}<${node.type} ${attrs} />`;
  const inner = kids.map((kid) => renderNode(kid, stroke, depth + 1)).join("\n");
  return `${indent}<${node.type} ${attrs}>\n${inner}\n${indent}</${node.type}>`;
}

async function loadGlyph(nodeModules, set, glyph) {
  const file = path.join(nodeModules, SETS[set].pkg, "dist/components", `${glyph}.js`);
  if (!existsSync(file)) fail(`${glyph} not found in ${SETS[set].pkg}`);
  const mod = await import(pathToFileURL(file).href);
  const component = mod[glyph];
  if (typeof component !== "function") fail(`${glyph} is not a component`);
  // Each glyph returns <Icon>{paths}</Icon>; rendering Icon once yields the <svg>.
  const iconElement = component({});
  const svg =
    typeof iconElement.type === "function" ? iconElement.type(iconElement.props) : iconElement;
  if (!isElement(svg) || svg.type !== "svg") fail(`${glyph} did not render an <svg>`);
  return { viewBox: svg.props.viewBox, nodes: flatten(svg.props.children) };
}

function renderFile({ notice, name, set, glyph, viewBox, nodes }) {
  const { pkg, version, stroke } = SETS[set];
  const usesStroke =
    stroke &&
    nodes.some(function hasStroke(node) {
      return "strokeWidth" in node.props || flatten(node.props.children).some(hasStroke);
    });
  const params = usesStroke
    ? '{ size = "1em", strokeWidth = 2, title, ...props }'
    : '{ size = "1em", title, ...props }';
  const body = nodes.map((node) => renderNode(node, usesStroke, 3)).join("\n");
  return `${notice}
// Generated by scripts/generate-icons.mjs from ${pkg}@${version} (${glyph}). Do not edit.

import type { IconProps } from "../icon-types";

export function ${componentName(name)}(${params}: IconProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="${viewBox}"
      data-slot="icon"
      aria-hidden={title === undefined ? true : undefined}
      role={title === undefined ? undefined : "img"}
      {...props}
    >
      {title === undefined ? null : <title>{title}</title>}
${body}
    </svg>
  );
}
`;
}

async function main() {
  const nodeModules = process.argv[2] ?? process.env.NUCLEO_NODE_MODULES;
  if (!nodeModules) fail("pass the path to the licensed node_modules directory");
  const resolvedModules = path.resolve(nodeModules);
  if (resolvedModules.startsWith(`${repoDir}${path.sep}`)) {
    fail("the licensed node_modules must live outside the repository");
  }

  for (const { pkg, version } of Object.values(SETS)) {
    const manifest = path.join(resolvedModules, pkg, "package.json");
    if (!existsSync(manifest)) fail(`${pkg} is not installed in ${resolvedModules}`);
    const installed = JSON.parse(await readFile(manifest, "utf8")).version;
    if (installed !== version) fail(`${pkg} is ${installed}, expected ${version}`);
  }

  const list = JSON.parse(await readFile(path.join(iconDir, "icons.json"), "utf8"));
  const entries = Object.entries(list).toSorted(([a], [b]) => a.localeCompare(b));
  if (entries.length > MAX_GLYPHS)
    fail(`${entries.length} icons exceed the ${MAX_GLYPHS}-glyph budget`);

  const notice = formatNotice(
    await readFile(path.join(packageDir, "scripts/nucleo-notice.txt"), "utf8"),
  );
  await mkdir(outDir, { recursive: true });
  const written = new Set();

  for (const [name, { set, glyph }] of entries) {
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(name)) fail(`"${name}" is not kebab-case`);
    if (!(set in SETS)) fail(`${name}: unknown set "${set}"`);
    if (!/^Icon[A-Za-z0-9]+$/.test(glyph)) fail(`${name}: invalid glyph "${glyph}"`);
    const { viewBox, nodes } = await loadGlyph(resolvedModules, set, glyph);
    const file = `${name}.tsx`;
    await writeFile(
      path.join(outDir, file),
      renderFile({ notice, name, set, glyph, viewBox, nodes }),
    );
    written.add(file);
  }

  const index = entries
    .map(([name]) => `export { ${componentName(name)} } from "./${name}";`)
    .join("\n");
  await writeFile(
    path.join(outDir, "index.ts"),
    `// Generated by scripts/generate-icons.mjs. Do not edit.\n\n${index}\n`,
  );
  written.add("index.ts");

  for (const file of await readdir(outDir)) {
    if (!written.has(file)) await rm(path.join(outDir, file));
  }

  const oxfmt = path.join(repoDir, "node_modules/.bin/oxfmt");
  if (existsSync(oxfmt)) {
    const result = spawnSync(oxfmt, [outDir], { cwd: repoDir, stdio: "inherit" });
    if (result.status !== 0) fail("oxfmt failed on the generated files");
  } else {
    console.warn("generate-icons: oxfmt not found; run `pnpm format` before committing");
  }

  console.log(`generate-icons: wrote ${entries.length} icons to ${path.relative(repoDir, outDir)}`);
}

if (import.meta.main) {
  await main();
}
